import{_ as a,o as t,c as s,a0 as o}from"./chunks/framework.CKZJaUMN.js";const u=JSON.parse('{"title":"Boundary with sepia and peregrin","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/boundary.md","filePath":"explanation/boundary.md"}'),n={name:"explanation/boundary.md"};function i(r,e,p,h,d,c){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="boundary-with-sepia-and-peregrin" tabindex="-1">Boundary with sepia and peregrin <a class="header-anchor" href="#boundary-with-sepia-and-peregrin" aria-label="Permalink to &quot;Boundary with sepia and peregrin&quot;">​</a></h1><p>Hypha sits between two neighbors and must stay generic against both.</p><h2 id="sepia-—-session-mechanism" tabindex="-1">sepia — session <em>mechanism</em> <a class="header-anchor" href="#sepia-—-session-mechanism" aria-label="Permalink to &quot;sepia — session *mechanism*&quot;">​</a></h2><p>Sepia owns everything you can do <strong>to</strong> a session: attach, prompt, restore, rewind, per-agent stores. It is deliberately just the agent-session abstraction — it must never learn about locks, multi-node, or orchestration.</p><p>Hypha&#39;s side of the contract: the <code>sepia-peregrin</code> adapter (which lives <strong>in the sepia repo</strong>) registers <code>kind=&quot;sepia-session&quot;</code> entities, translates entity ops ↔ session verbs, and implements snapshot as sepia&#39;s session IR export/import. Hypha never names a sepia type; sepia never learns hypha exists — the adapter is the only coupling, and it depends on hypha&#39;s public API, never the reverse.</p><h2 id="peregrin-—-orchestration-policy-campaigns" tabindex="-1">peregrin — orchestration <em>policy + campaigns</em> <a class="header-anchor" href="#peregrin-—-orchestration-policy-campaigns" aria-label="Permalink to &quot;peregrin — orchestration *policy + campaigns*&quot;">​</a></h2><p>Peregrin owns campaigns (declarative event-driven workflows), drivers, loaders, and policy (who may act, when, from where). Post PL-005, peregrin&#39;s distributed layer <strong>is</strong> hypha: <code>peregrin-node</code> becomes a thin composition root that registers entity planes — <code>sepia-session</code> (via the adapter) and <code>campaign</code> (its own <code>campaign_entity.rs</code>) — on a hypha node host.</p><p>The dependency direction is one-way:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>peregrin (orchestration) → hypha (substrate) → ports</span></span></code></pre></div><p>Orchestration may sit <em>on</em> the substrate; the substrate never imports orchestration. <code>peregrin-hub</code>&#39;s gateway role moves to <code>hypha-hub</code>; peregrin keeps campaign verbs in its CLI.</p><h2 id="the-rule-of-thumb" tabindex="-1">The rule of thumb <a class="header-anchor" href="#the-rule-of-thumb" aria-label="Permalink to &quot;The rule of thumb&quot;">​</a></h2><ul><li>&quot;Something you do to a workload&quot; → the integration repo.</li><li>&quot;Who may act on entity X, when, from where&quot; → hypha.</li><li>&quot;A workflow of events and steps&quot; → peregrin.</li></ul>',12)])])}const m=a(n,[["render",i]]);export{u as __pageData,m as default};
